-- Create "workspaces" table
CREATE TABLE "public"."workspaces" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "slug" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "workspaces_slug_key" to table: "workspaces"
CREATE UNIQUE INDEX "workspaces_slug_key" ON "public"."workspaces" ("slug");
-- Create "projects" table
CREATE TABLE "public"."projects" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "projects_workspaces_projects" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create "workspace_memberships" table
CREATE TABLE "public"."workspace_memberships" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "role" character varying NOT NULL DEFAULT 'member',
  "created_at" timestamptz NOT NULL,
  "user_id" bigint NULL,
  "workspace_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "workspace_memberships_users_workspace_memberships" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "workspace_memberships_workspaces_memberships" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "workspacemembership_user_id_workspace_id" to table: "workspace_memberships"
CREATE UNIQUE INDEX "workspacemembership_user_id_workspace_id" ON "public"."workspace_memberships" ("user_id", "workspace_id");
-- Modify "api_tokens" table
ALTER TABLE "public"."api_tokens" ADD COLUMN "workspace_project_id" bigint NULL;
ALTER TABLE "public"."api_tokens" ADD CONSTRAINT "api_tokens_projects_api_tokens" FOREIGN KEY ("workspace_project_id") REFERENCES "public"."projects" ("id") ON UPDATE NO ACTION ON DELETE SET NULL;
-- Modify "contacts" table
ALTER TABLE "public"."contacts" ADD COLUMN "workspace_project_id" bigint NULL;
DROP INDEX "public"."contacts_email_key";
CREATE UNIQUE INDEX "contact_email_workspace_project_id" ON "public"."contacts" ("email", "workspace_project_id");
ALTER TABLE "public"."contacts" ADD CONSTRAINT "contacts_projects_contacts" FOREIGN KEY ("workspace_project_id") REFERENCES "public"."projects" ("id") ON UPDATE NO ACTION ON DELETE SET NULL;
-- Modify "events" table
ALTER TABLE "public"."events" ADD COLUMN "workspace_project_id" bigint NULL;
ALTER TABLE "public"."events" ADD CONSTRAINT "events_projects_events" FOREIGN KEY ("workspace_project_id") REFERENCES "public"."projects" ("id") ON UPDATE NO ACTION ON DELETE SET NULL;
-- Modify "tracking_profiles" table
ALTER TABLE "public"."tracking_profiles" ADD COLUMN "workspace_project_id" bigint NULL;
DROP INDEX "public"."tracking_profiles_email_key";
DROP INDEX "public"."tracking_profiles_phone_key";
DROP INDEX "public"."tracking_profiles_subject_id_key";
CREATE UNIQUE INDEX "trackingprofile_subject_id_workspace_project_id" ON "public"."tracking_profiles" ("subject_id", "workspace_project_id");
CREATE UNIQUE INDEX "trackingprofile_email_workspace_project_id" ON "public"."tracking_profiles" ("email", "workspace_project_id");
CREATE UNIQUE INDEX "trackingprofile_phone_workspace_project_id" ON "public"."tracking_profiles" ("phone", "workspace_project_id");
ALTER TABLE "public"."tracking_profiles" ADD CONSTRAINT "tracking_profiles_projects_tracking_profiles" FOREIGN KEY ("workspace_project_id") REFERENCES "public"."projects" ("id") ON UPDATE NO ACTION ON DELETE SET NULL;
